import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Poligoni regolari circoscritti ad una circonferenza","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fr/frc.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fr/frc.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fr/frc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="poligoni-regolari-circoscritti-ad-una-circonferenza" tabindex="-1">Poligoni regolari circoscritti ad una circonferenza <a class="header-anchor" href="#poligoni-regolari-circoscritti-ad-una-circonferenza" aria-label="Permalink to “Poligoni regolari circoscritti ad una circonferenza”">​</a></h1><p>Enuncio alcune proprietà senza dimostrazione</p><p>Abbiamo che: <strong>Dato un qualsiasi poligono regolare è sempre possibile circoscriverlo ad una circonferenza</strong></p><blockquote><p>In questo caso i raggi dei cerchi coincidono con le apoteme dei vari poligoni regolari</p></blockquote><p>Inoltre avremo che <strong>All&#39;aumentare del numero dei lati la misura del perimetro di un poligono regolare circoscritto ad una circonferenza diminuisce avvicinandosi alla misura della lunghezza della circonferenza stessa</strong></p><p>Ad esempio se considero il quadrato circoscritto e poi l&#39;ottagono regolare circoscritto avremo che il perimetro dell&#39;ottagono è minore del perimetro del quadrato ma maggiore della lunghezza della circonferenza:</p><p>Infatti, se considero il triangolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>P</mi><mi>Q</mi></mrow><annotation encoding="application/x-tex">APQ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal">Q</span></span></span></span>, siccome in ogni triangolo un lato è minore della somma degli altri due, avremo</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>P</mi><mi>Q</mi><mo>&lt;</mo><mi>A</mi><mi>P</mi><mo>+</mo><mi>A</mi><mi>Q</mi></mrow><annotation encoding="application/x-tex">PQ &lt; AP + AQ </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal">Q</span></span></span></span></span></p><p>applicando tale ragionamento opportunamente ai lati del quadrato e dell&#39;ottagono ottengo la proprietà</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};